<?php require_once __DIR__.'/../../config/app.php';requireAdmin();$id=(int)($_GET['id']??0);if($id>0){try{$pdo->beginTransaction();$s=$pdo->prepare('DELETE FROM employees WHERE employee_id=?');$s->execute([$id]);$pdo->commit();$_SESSION['success']='Data berhasil dihapus.';}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['errors']=['form'=>'Data gagal dihapus.'];}}redirect('/pages/employees/index.php');